/// A ring of segments over the application's pool, split into
/// the two endpoint handles with [`Ring::split`].
pub struct Ring<'a> {
    /// Geometry and segment addresses.
    segs: Segments,
    _region: core::marker::PhantomData<&'a [u8]>,
}

